      "term": {
        "text": "primitive type",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "a basic data type in Java that is stored directly by the Java Runtime Environment without requiring explicit memory allocation by the programmer",
        "refs": ["Q0000"]
      },
      "context": null
    },
    {
      "term": {
        "text": "reference type",
        "refs": ["Q0000"]
      },
      "definition_text": {
        "text": "a type that refers to an object; memory for the object must be allocated explicitly with the new operator",
        "refs": ["Q0000", "Q0003"]
      },
      "context": null
    },
    {
      "term": {
        "text": "package",
        "refs": ["Q0001"]
      },
      "definition_text": {
        "text": "a namespace that groups related classes and interfaces, allowing the same class name to exist in different packages without conflict",
        "refs": ["Q0001"]
      },
      "context": null
    },
    {
      "term": {
        "text": "import",
        "refs": ["Q0002"]
