      "definition_text": {
        "text": "a statement that makes a class from another package available in the current source file",
        "refs": ["Q0002"]
      },
      "context": null
    },
    {
      "term": {
        "text": "new operator",
        "refs": ["Q0003"]
      },
      "definition_text": {
        "text": "an operator used to allocate memory for a new object of a reference type",
        "refs": ["Q0003"]
      },
      "context": null
    },
    {
      "term": {
        "text": "class",
        "refs": ["Q0004"]
      },
      "definition_text": {
