      },
      "context": null
    },
    {
      "term": {
        "text": "dot operator",
        "refs": ["Q0004"]
      },
      "definition_text": {
        "text": "the '.' symbol used to access members (fields or methods) of an object or class",
        "refs": ["Q0004"]
      },
      "context": null
    }
