  "explanations": [
    {
      "topic": {
        "text": "difference between primitive and reference types",
        "refs": ["Q0000", "Q0003"]
      },
      "explanation_text": {
        "text": "Primitive types are allocated and released automatically by the Java Runtime Environment, whereas reference types require explicit memory allocation with the new operator and are automatically reclaimed by the runtime when no longer referenced.",
        "refs": ["Q0000", "Q0003"]
      },
      "explanation_type": null
    },
    {
      "topic": {
        "text": "use of packages to avoid naming conflicts",
        "refs": ["Q0001"]
      },
      "explanation_text": {
        "text": "Packages create separate namespaces, allowing classes with the same name (e.g., Date) to exist in different packages such as java.util and java.sql without conflict.",
        "refs": ["Q0001"]
      },
      "explanation_type": null
    }
  ],
  "facts": [
    {
      "fact_text": {
        "text": "Java has eight primitive types.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "When declaring a reference type variable, you must use the new operator to allocate memory for the object.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "The Java Runtime Environment automatically releases memory for objects when they are no longer referenced.",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "IntelliJ IDEA can suggest class names and automatically add import statements for classes from other packages.",
